create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '',created_at timestamptz not null default now());
create table public.assistants(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null default 'Jazz Asistant',system_prompt text not null default '',settings jsonb not null default '{}',published_version int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.flows(id uuid primary key default gen_random_uuid(),assistant_id uuid not null references public.assistants(id) on delete cascade,name text not null,status text not null default 'draft' check(status in('draft','published','archived')),version int not null default 1,created_at timestamptz not null default now());
create table public.flow_nodes(id uuid primary key default gen_random_uuid(),flow_id uuid not null references public.flows(id) on delete cascade,node_type text not null,name text not null,config jsonb not null default '{}',position jsonb not null default '{"x":0,"y":0}',created_at timestamptz not null default now());
create table public.flow_edges(id uuid primary key default gen_random_uuid(),flow_id uuid not null references public.flows(id) on delete cascade,source_id uuid not null references public.flow_nodes(id) on delete cascade,target_id uuid not null references public.flow_nodes(id) on delete cascade,condition jsonb not null default '{}');
create table public.provider_profiles(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,provider text not null,secret_name text not null,key_count int not null default 0,enabled boolean not null default true,priority int not null default 100,model text,settings jsonb not null default '{}',unique(owner_id,provider));
create table public.conversations(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,assistant_id uuid references public.assistants(id) on delete set null,title text not null default 'Yeni konuşma',summary text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.messages(id bigint generated always as identity primary key,conversation_id uuid not null references public.conversations(id) on delete cascade,role text not null check(role in('user','assistant','system','tool')),content text not null,provider text,model text,input_tokens int,output_tokens int,latency_ms int,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.usage_events(id bigint generated always as identity primary key,owner_id uuid not null references public.profiles(id) on delete cascade,provider text,model text,success boolean not null,error_code text,input_tokens int default 0,output_tokens int default 0,cost_usd numeric(12,6) default 0,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.assistants enable row level security;alter table public.flows enable row level security;alter table public.flow_nodes enable row level security;alter table public.flow_edges enable row level security;alter table public.provider_profiles enable row level security;alter table public.conversations enable row level security;alter table public.messages enable row level security;alter table public.usage_events enable row level security;
create policy own_profile on public.profiles for all using(id=(select auth.uid())) with check(id=(select auth.uid()));create policy own_assistant on public.assistants for all using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));create policy own_provider on public.provider_profiles for all using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));create policy own_conversation on public.conversations for all using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));create policy own_usage on public.usage_events for select using(owner_id=(select auth.uid()));
create policy own_flow on public.flows for all using(exists(select 1 from public.assistants a where a.id=assistant_id and a.owner_id=(select auth.uid()))) with check(exists(select 1 from public.assistants a where a.id=assistant_id and a.owner_id=(select auth.uid())));create policy own_nodes on public.flow_nodes for all using(exists(select 1 from public.flows f join public.assistants a on a.id=f.assistant_id where f.id=flow_id and a.owner_id=(select auth.uid()))) with check(exists(select 1 from public.flows f join public.assistants a on a.id=f.assistant_id where f.id=flow_id and a.owner_id=(select auth.uid())));create policy own_edges on public.flow_edges for all using(exists(select 1 from public.flows f join public.assistants a on a.id=f.assistant_id where f.id=flow_id and a.owner_id=(select auth.uid()))) with check(exists(select 1 from public.flows f join public.assistants a on a.id=f.assistant_id where f.id=flow_id and a.owner_id=(select auth.uid())));create policy own_messages on public.messages for all using(exists(select 1 from public.conversations c where c.id=conversation_id and c.owner_id=(select auth.uid()))) with check(exists(select 1 from public.conversations c where c.id=conversation_id and c.owner_id=(select auth.uid())));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'name',''));insert into public.assistants(owner_id) values(new.id);return new;end$$;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create index messages_conversation_created_idx on public.messages(conversation_id,created_at);create index usage_owner_created_idx on public.usage_events(owner_id,created_at desc);